create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create type public.game_mode as enum('quick','standard','long','custom');
create type public.game_phase as enum('lobby','team_reveal','question','minigame','building','voting','results');
create type public.team_side as enum('A','B');
alter table rooms alter column id set default gen_random_uuid();
alter table rooms add code text unique default upper(left(gen_random_uuid()::text,6)),add mode game_mode default 'standard',add phase game_phase default 'lobby',add closed_at timestamptz,add created_at timestamptz default now(),add solo_since timestamptz,add jokers_per_team int,add selected_games text[],add selected_games_locked bool;
alter table players alter column id set default gen_random_uuid();
alter table players alter column team_side type public.team_side using team_side::public.team_side;
alter table players add nickname text not null default 'QA',add is_bot bool not null default false;
create unique index players_nickname_uq on players(room_id,lower(nickname));
create unique index players_member_uq on players(room_id,user_id);
alter table party_events add kind text,add prompt text,add created_at timestamptz default now();
alter table round_answers add room_id uuid;
alter table friend_facts add room_id uuid;
alter table survivor_team_messages add id bigint generated always as identity,add minigame_id uuid,add side public.team_side,add created_at timestamptz default now();
create table party_event_votes(event_id uuid references party_events on delete cascade,player_id uuid references players on delete cascade,answer text);
create table room_teams(room_id uuid references rooms on delete cascade,side public.team_side,creature_name text,creature_title text);
create function public.gen_room_code() returns text language sql as $$select upper(left(gen_random_uuid()::text,6))$$;
create function public._close_idle_rooms() returns void language sql as $$select$$;
